import React, { useEffect, useState } from "react";
import Navbar from "../components/Navbar";
import { dashboardAPI, doctorAPI } from "../services/api";
import { useAuth } from "../context/AuthContext";

export default function DoctorDashboard() {
  const { user: authUser } = useAuth();
  const [data, setData] = useState(null);
  const [error, setError] = useState("");
  const [toggleForm, setToggleForm] = useState({ specialization: "", availableFrom: "", availableTo: "" });
  const [saving, setSaving] = useState(false);
  const [successMsg, setSuccessMsg] = useState("");

  const load = () => dashboardAPI.get().then(({ data }) => setData(data)).catch(() => setError("Failed to load dashboard"));

  useEffect(() => { load(); }, []);

  const handleToggle = async (e) => {
    e.preventDefault();
    setSaving(true);
    setSuccessMsg("");
    try {
      const res = await doctorAPI.toggleAvailability(toggleForm);
      setSuccessMsg(res.data.message);
      load();
    } catch (err) {
      setError(err.response?.data?.message || "Update failed");
    } finally {
      setSaving(false);
    }
  };

  if (error) return <div className="page"><Navbar /><div className="container main-content"><div className="alert alert-error">{error}</div></div></div>;
  if (!data) return <div className="loading-screen"><span className="spinner"></span></div>;

  const { user, likelyRecords } = data;

  return (
    <div className="page">
      <Navbar />
      <main className="container main-content">
        <div style={{ marginBottom: "1.5rem" }}>
          <h1 style={{ fontSize: "1.5rem", fontWeight: 700 }}>Welcome, Dr. {user.name} 👨‍⚕️</h1>
          <p style={{ color: "var(--text-muted)", fontSize: ".9rem" }}>Doctor Dashboard · {user.specialization || "General Physician"}</p>
        </div>

        <div className="grid-2" style={{ marginBottom: "1.5rem" }}>
          {/* Availability card */}
          <div className="card">
            <h3 className="card-title">Availability Status</h3>
            <div style={{ display: "flex", alignItems: "center", gap: "1rem", marginBottom: "1rem" }}>
              <span className={`badge ${user.isAvailable ? "badge-success" : "badge-warning"}`} style={{ fontSize: ".95rem", padding: ".3rem .8rem" }}>
                {user.isAvailable ? "● Online" : "○ Offline"}
              </span>
              {user.availableFrom && user.availableTo && (
                <span style={{ fontSize: ".85rem", color: "var(--text-muted)" }}>{user.availableFrom} – {user.availableTo}</span>
              )}
            </div>
            {successMsg && <div className="alert alert-success">{successMsg}</div>}
            <form onSubmit={handleToggle}>
              <div className="form-group">
                <label>Specialization</label>
                <input className="form-control" value={toggleForm.specialization} onChange={e => setToggleForm({ ...toggleForm, specialization: e.target.value })} placeholder={user.specialization || "General Physician"} />
              </div>
              <div className="form-row">
                <div className="form-group">
                  <label>From</label>
                  <input className="form-control" type="time" value={toggleForm.availableFrom} onChange={e => setToggleForm({ ...toggleForm, availableFrom: e.target.value })} />
                </div>
                <div className="form-group">
                  <label>To</label>
                  <input className="form-control" type="time" value={toggleForm.availableTo} onChange={e => setToggleForm({ ...toggleForm, availableTo: e.target.value })} />
                </div>
              </div>
              <button className="btn btn-primary" type="submit" disabled={saving}>
                {saving ? <><span className="spinner"></span> Saving…</> : `Toggle to ${user.isAvailable ? "Offline" : "Online"}`}
              </button>
            </form>
          </div>

          {/* Stats */}
          <div className="card" style={{ display: "flex", flexDirection: "column", gap: "1rem" }}>
            <h3 className="card-title">Statistics</h3>
            <div className="grid-2">
              <div className="card stat-card">
                <div className="stat-value">{likelyRecords.length}</div>
                <div className="stat-label">High-Risk Patients</div>
              </div>
              <div className="card stat-card">
                <div className="stat-value" style={{ color: user.isAvailable ? "var(--success)" : "var(--text-muted)" }}>
                  {user.isAvailable ? "Online" : "Offline"}
                </div>
                <div className="stat-label">Current Status</div>
              </div>
            </div>
          </div>
        </div>

        {/* High-risk patients table */}
        <div className="card">
          <h3 className="card-title">⚠️ High-Risk Patients</h3>
          {likelyRecords.length === 0 ? (
            <p style={{ color: "var(--text-muted)", fontSize: ".9rem" }}>No high-risk assessments on record.</p>
          ) : (
            <div className="table-wrap">
              <table>
                <thead>
                  <tr><th>Patient</th><th>Email</th><th>Risk %</th><th>Age</th><th>Date</th></tr>
                </thead>
                <tbody>
                  {likelyRecords.map((r) => (
                    <tr key={r._id}>
                      <td><strong>{r.patientId?.name || "—"}</strong></td>
                      <td>{r.patientId?.email || "—"}</td>
                      <td><span className="badge badge-danger">{r.riskProbability}%</span></td>
                      <td>{r.age}</td>
                      <td>{new Date(r.createdAt).toLocaleDateString()}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </main>
    </div>
  );
}
